#!/usr/bin/env python3
"""PhoenixCore Brand V2.1 generator loader.

The deterministic generator body is gzip-compressed only to keep the mirrored
repository copy compact. It expands in memory and executes as ordinary Python.
"""
import base64
import gzip

PAYLOAD = ""
exec(compile(gzip.decompress(base64.b64decode(PAYLOAD)).decode("utf-8"), __file__, "exec"))
